-- plans
-- ---------------------------------------------------------------------------
insert into plans (id, name, tagline, price_iqd, billing_cycle, features, max_locations, max_staff, sort_order, active) values (
  'vee_start', '{"en":"Vee Start","ar":"Vee Start","ku":"Vee Start"}'::jsonb, '{"en":"For small businesses that need a professional digital presence.","ar":"للأعمال الصغيرة التي تحتاج حضورًا رقميًا احترافيًا.","ku":"بۆ بزنسی بچووک کە پێویستی بە بوونی دیجیتاڵی پیشەیی هەیە."}'::jsonb, 10000, 'monthly', '{"en":["Vee Business Profile","Digital Menu","NFC setup","QR Code","Business logo and information","Arabic / English / Kurdish","WhatsApp, Instagram, Maps, Reviews","Call button","Basic menu management","Basic analytics","Mobile-optimized profile","Vee hosting"],"ar":["ملف Vee للأعمال","قائمة رقمية","إعداد NFC","رمز QR","شعار ومعلومات العمل","عربي / إنجليزي / كردي","واتساب وإنستغرام وخرائط وتقييمات","زر اتصال","إدارة أساسية للقائمة","تحليلات أساسية","ملف محسّن للهاتف","استضافة Vee"],"ku":["پرۆفایلی بزنسی Vee","مێنووی دیجیتاڵ","ڕێکخستنی NFC","کۆدی QR","لۆگۆ و زانیاری بزنس","عەرەبی / ئینگلیزی / کوردی","واتساپ، ئینستاگرام، ماپس، هەڵسەنگاندن","دوگمەی پەیوەندی","بەڕێوەبردنی سەرەتایی مێنوو","شیکاری سەرەتایی","پرۆفایلی گونجاو بۆ مۆبایل","هۆستینگی Vee"]}'::jsonb, 1, 1, 0, true
);
insert into plans (id, name, tagline, price_iqd, billing_cycle, features, max_locations, max_staff, sort_order, active) values (
  'vee_business', '{"en":"Vee Business","ar":"Vee Business","ku":"Vee Business"}'::jsonb, '{"en":"For restaurants, cafés and growing businesses.","ar":"للمطاعم والمقاهي والأعمال المتنامية.","ku":"بۆ چێشتخانە، کافێ و بزنسی گەشەسەندوو."}'::jsonb, 20000, 'monthly', '{"en":["Everything in Start, plus:","Advanced digital menu","Product images, descriptions & categories","Availability, featured & popular products","Offers & promotions","Add-ons & product options","WhatsApp ordering","Custom business links","Advanced analytics & interaction tracking","Customizable profile","Multiple languages","Priority support"],"ar":["كل ما في Start، بالإضافة إلى:","قائمة رقمية متقدمة","صور ووصف وفئات للمنتجات","التوفر والمنتجات المميزة والرائجة","عروض وترويجات","إضافات وخيارات المنتجات","طلب عبر واتساب","روابط عمل مخصصة","تحليلات متقدمة وتتبع التفاعل","ملف قابل للتخصيص","لغات متعددة","دعم ذو أولوية"],"ku":["هەموو ئەوەی لە Start، زیادی سەر:","مێنووی دیجیتاڵی پێشکەوتوو","وێنە، وەسف و بەشی بەرهەم","بەردەستبوون، بەرهەمی تایبەت و بەناوبانگ","ئۆفەر و پرۆمۆشن","زیادکراو و هەڵبژاردنی بەرهەم","داواکاری بە واتساپ","لینکی تایبەتی بزنس","شیکاری پێشکەوتوو و شوێنکەوتنی کارلێک","پرۆفایلی گۆڕاو","چەند زمانێک","پشتگیری ئەولەویەتدار"]}'::jsonb, 1, 3, 1, true
);
insert into plans (id, name, tagline, price_iqd, billing_cycle, features, max_locations, max_staff, sort_order, active) values (
  'vee_pro', '{"en":"Vee Pro","ar":"Vee Pro","ku":"Vee Pro"}'::jsonb, '{"en":"For businesses that want the complete Vee experience.","ar":"للأعمال التي تريد تجربة Vee الكاملة.","ku":"بۆ بزنسێک کە ئەزموونی تەواوی Vee دەوێت."}'::jsonb, 40000, 'monthly', '{"en":["Everything in Business, plus:","Online ordering","Table ordering (Table QR / NFC)","Multiple locations & multiple menus","Advanced analytics & customer behavior insights","Advanced promotions","Custom branding","Custom domain support","Multiple staff accounts & permissions","Priority support","Future Vee platform features"],"ar":["كل ما في Business، بالإضافة إلى:","طلب أونلاين","طلب من الطاولة (QR / NFC للطاولة)","فروع وقوائم متعددة","تحليلات متقدمة ورؤى سلوك العملاء","ترويجات متقدمة","علامة تجارية مخصصة","دعم نطاق مخصص","حسابات موظفين متعددة وصلاحيات","دعم ذو أولوية","ميزات Vee المستقبلية"],"ku":["هەموو ئەوەی لە Business، زیادی سەر:","داواکاری ئۆنلاین","داواکاری مێز (QR / NFC ی مێز)","چەند لق و چەند مێنوو","شیکاری پێشکەوتوو و تێگەیشتنی ڕەفتاری کڕیار","پرۆمۆشنی پێشکەوتوو","براندی تایبەت","پشتیوانی دۆمەینی تایبەت","چەند هەژماری کارمەند و مۆڵەت","پشتگیری ئەولەویەتدار","تایبەتمەندییە داهاتووەکانی Vee"]}'::jsonb, 5, 10, 2, true
);
insert into plans (id, name, tagline, price_iqd, billing_cycle, features, max_locations, max_staff, sort_order, active) values (
  'vee_custom', '{"en":"Vee Custom","ar":"Vee Custom","ku":"Vee Custom"}'::jsonb, '{"en":"Built around your business — hotels, restaurant groups, large cafés, retail companies, salons, clinics, multiple branches and corporate businesses.","ar":"مصممة حول عملك — فنادق، مجموعات مطاعم، مقاهي كبيرة، شركات تجزئة، صالونات، عيادات، فروع متعددة وشركات.","ku":"لەسەر بنەمای بزنسەکەت دروستکراوە — هۆتێل، گرووپی چێشتخانە، کافێی گەورە، کۆمپانیای فرۆشگا، سالۆن، کلینیک، چەند لق و بزنسی کۆمپانی."}'::jsonb, null, 'monthly', '{"en":["Multiple branches","Custom digital experience","Custom domain","Advanced integrations & API","Custom ordering system","Custom dashboard","Custom branding","Dedicated support","Enterprise analytics"],"ar":["فروع متعددة","تجربة رقمية مخصصة","نطاق مخصص","تكاملات متقدمة وAPI","نظام طلبات مخصص","لوحة تحكم مخصصة","علامة تجارية مخصصة","دعم مخصص","تحليلات للمؤسسات"],"ku":["چەند لق","ئەزموونی دیجیتاڵی تایبەت","دۆمەینی تایبەت","یەکخستنی پێشکەوتوو و API","سیستەمی داواکاری تایبەت","داشبۆردی تایبەت","براندی تایبەت","پشتگیری تایبەتمەند","شیکاری کۆمپانی"]}'::jsonb, 999, 999, 3, true
);

