insert into catalogue_products (sku, category, name, description, features, specifications, price_iqd, request_quote, images, colors, status, sort_order, featured, seo_title, seo_description, cta_type) values (
  'VEE-NFC-CUSTOM', 'nfc_card', '{"en":"Vee Custom NFC Card","ar":"بطاقة Vee NFC المخصصة","ku":"کارتی Vee NFC ی تایبەت"}'::jsonb, '{"en":"A custom NFC card carrying your business name and logo. One tap opens your chosen destination — your profile, links, menu, contact details, or anywhere else you decide to send customers.","ar":"بطاقة NFC مخصصة تحمل اسم عملك وشعارك. لمسة واحدة تفتح الوجهة التي تختارها — ملفك، روابطك، قائمتك، بيانات التواصل، أو أي وجهة أخرى تحددها.","ku":"کارتێکی NFC ی تایبەت کە ناو و لۆگۆی بزنسەکەت لەسەریەتی. یەک دەستلێدان ئەو ناونیشانە دەکاتەوە کە هەڵتبژاردووە — پرۆفایل، لینک، مێنوو، زانیاری پەیوەندی یان هەر شوێنێکی تر."}'::jsonb, '{"en":["Printed with your business name & logo","Opens any destination you choose","Reprogrammable at any time from your dashboard","Available in black and white"],"ar":["مطبوعة باسم وشعار عملك","تفتح أي وجهة تختارها","قابلة لإعادة البرمجة في أي وقت من لوحة التحكم","متوفرة باللونين الأسود والأبيض"],"ku":["چاپکراو بە ناو و لۆگۆی بزنسەکەت","هەر ناونیشانێک کە هەڵتبژێریت دەکاتەوە","لە هەر کاتێک دەتوانرێت لە داشبۆردەوە دووبارە بەرنامەسازی بکرێت","بە ڕەنگی ڕەش و سپی بەردەستە"]}'::jsonb, '{}'::jsonb, null, true, '["/brand/product-nfc-card-custom.svg"]'::jsonb, '["black","white"]'::jsonb, 'published', 0, true, '{"en":"Vee Custom NFC Card","ar":"بطاقة Vee NFC المخصصة","ku":"کارتی Vee NFC ی تایبەت"}'::jsonb, '{"en":"A custom NFC card carrying your business name and logo. One tap opens your chosen destination — your profile, links, menu, contact details, or anywhere els","ar":"بطاقة NFC مخصصة تحمل اسم عملك وشعارك. لمسة واحدة تفتح الوجهة التي تختارها — ملفك، روابطك، قائمتك، بيانات التواصل، أو أي وجهة أخرى تحددها.","ku":"کارتێکی NFC ی تایبەت کە ناو و لۆگۆی بزنسەکەت لەسەریەتی. یەک دەستلێدان ئەو ناونیشانە دەکاتەوە کە هەڵتبژاردووە — پرۆفایل، لینک، مێنوو، زانیاری پەیوەندی یان ه"}'::jsonb, 'enquire'
);
insert into catalogue_products (sku, category, name, description, features, specifications, price_iqd, request_quote, images, colors, status, sort_order, featured, seo_title, seo_description, cta_type) values (
  'VEE-NFC-GREVIEW', 'nfc_card', '{"en":"Vee Google Review NFC Card","ar":"بطاقة Vee NFC لتقييمات غوغل","ku":"کارتی Vee NFC بۆ هەڵسەنگاندنی گووگڵ"}'::jsonb, '{"en":"Send customers straight to your Google Review page with one tap — the fastest way to turn a happy customer into a 5-star review, right at the table or counter.","ar":"أرسل عملاءك مباشرة إلى صفحة تقييمك على غوغل بلمسة واحدة — أسرع طريقة لتحويل عميل راضٍ إلى تقييم خمس نجوم، مباشرة عند الطاولة أو الكاونتر.","ku":"کڕیارەکانت بە یەک دەستلێدان ڕاستەوخۆ بنێرە بۆ پەڕەی هەڵسەنگاندنی گووگڵ — خێراترین ڕێگا بۆ گۆڕینی کڕیارێکی دڵخۆش بۆ هەڵسەنگاندنی 5 ئەستێرە."}'::jsonb, '{"en":["One tap to your Google Review page","No app required for the customer","Boosts review volume and rating","Available in black and white"],"ar":["لمسة واحدة إلى صفحة تقييمك على غوغل","لا حاجة لتطبيق من طرف العميل","يزيد عدد التقييمات والتقييم العام","متوفرة باللونين الأسود والأبيض"],"ku":["یەک دەستلێدان بۆ پەڕەی هەڵسەنگاندنی گووگڵ","پێویست بە ئەپ ناکات بۆ کڕیار","ژمارە و ئاستی هەڵسەنگاندن بەرز دەکاتەوە","بە ڕەنگی ڕەش و سپی بەردەستە"]}'::jsonb, '{}'::jsonb, null, true, '["/brand/product-nfc-card-greview.svg"]'::jsonb, '["black","white"]'::jsonb, 'published', 1, true, '{"en":"Vee Google Review NFC Card","ar":"بطاقة Vee NFC لتقييمات غوغل","ku":"کارتی Vee NFC بۆ هەڵسەنگاندنی گووگڵ"}'::jsonb, '{"en":"Send customers straight to your Google Review page with one tap — the fastest way to turn a happy customer into a 5-star review, right at the table or coun","ar":"أرسل عملاءك مباشرة إلى صفحة تقييمك على غوغل بلمسة واحدة — أسرع طريقة لتحويل عميل راضٍ إلى تقييم خمس نجوم، مباشرة عند الطاولة أو الكاونتر.","ku":"کڕیارەکانت بە یەک دەستلێدان ڕاستەوخۆ بنێرە بۆ پەڕەی هەڵسەنگاندنی گووگڵ — خێراترین ڕێگا بۆ گۆڕینی کڕیارێکی دڵخۆش بۆ هەڵسەنگاندنی 5 ئەستێرە."}'::jsonb, 'enquire'
);
insert into catalogue_products (sku, category, name, description, features, specifications, price_iqd, request_quote, images, colors, status, sort_order, featured, seo_title, seo_description, cta_type) values (
  'VEE-NFC-MIFARE', 'nfc_card', '{"en":"Vee MIFARE NFC Card","ar":"بطاقة Vee MIFARE NFC","ku":"کارتی Vee MIFARE NFC"}'::jsonb, '{"en":"A MIFARE-standard NFC card for businesses that need it for access, loyalty, or other MIFARE-compatible applications, alongside your Vee digital experience.","ar":"بطاقة NFC بمعيار MIFARE للأعمال التي تحتاجها للدخول، برامج الولاء، أو تطبيقات أخرى متوافقة مع MIFARE، إلى جانب تجربة Vee الرقمية.","ku":"کارتێکی NFC ی ستانداردی MIFARE بۆ بزنسەکانێک کە پێویستیان پێیەتی بۆ چوونەژوورەوە، پرۆگرامی دڵسۆزی، یان بەکارهێنانی تری گونجاو لەگەڵ MIFARE، لەگەڵ ئەزموونی دیجیتاڵی Vee."}'::jsonb, '{"en":["MIFARE-standard chip","Compatible with existing access/loyalty systems","Carries your Vee profile link","Available in black and white"],"ar":["شريحة بمعيار MIFARE","متوافقة مع أنظمة الدخول والولاء الحالية","تحمل رابط ملفك على Vee","متوفرة باللونين الأسود والأبيض"],"ku":["چیپی ستانداردی MIFARE","گونجاوە لەگەڵ سیستەمی چوونەژوورەوە و دڵسۆزیی ئێستا","لینکی پرۆفایلی Vee ـت هەڵدەگرێت","بە ڕەنگی ڕەش و سپی بەردەستە"]}'::jsonb, '{}'::jsonb, null, true, '["/brand/product-nfc-card-mifare.svg"]'::jsonb, '["black","white"]'::jsonb, 'published', 2, false, '{"en":"Vee MIFARE NFC Card","ar":"بطاقة Vee MIFARE NFC","ku":"کارتی Vee MIFARE NFC"}'::jsonb, '{"en":"A MIFARE-standard NFC card for businesses that need it for access, loyalty, or other MIFARE-compatible applications, alongside your Vee digital experience.","ar":"بطاقة NFC بمعيار MIFARE للأعمال التي تحتاجها للدخول، برامج الولاء، أو تطبيقات أخرى متوافقة مع MIFARE، إلى جانب تجربة Vee الرقمية.","ku":"کارتێکی NFC ی ستانداردی MIFARE بۆ بزنسەکانێک کە پێویستیان پێیەتی بۆ چوونەژوورەوە، پرۆگرامی دڵسۆزی، یان بەکارهێنانی تری گونجاو لەگەڵ MIFARE، لەگەڵ ئەزموونی "}'::jsonb, 'enquire'
);
insert into catalogue_products (sku, category, name, description, features, specifications, price_iqd, request_quote, images, colors, status, sort_order, featured, seo_title, seo_description, cta_type) values (
  'VEE-ACRYLIC-STAND', 'acrylic', '{"en":"Vee Acrylic NFC Stand","ar":"حامل Vee الأكريليك NFC","ku":"ستاندی ئەکریلیکی Vee NFC"}'::jsonb, '{"en":"A premium acrylic table stand for restaurants and cafés. One tap opens your digital menu or business profile, and can include a table number for table-based ordering.","ar":"حامل طاولة أكريليك فاخر للمطاعم والمقاهي. لمسة واحدة تفتح قائمتك الرقمية أو ملف عملك، ويمكن أن يتضمن رقم الطاولة للطلب من الطاولة.","ku":"ستاندێکی مێزی ئەکریلیکی پرێمیۆم بۆ چێشتخانە و کافێکان. یەک دەستلێدان مێنووی دیجیتاڵ یان پرۆفایلی بزنسەکەت دەکاتەوە، و دەتوانێت ژمارەی مێز لەخۆبگرێت بۆ داواکاری لەسەر مێز."}'::jsonb, '{"en":["Premium clear acrylic construction","Opens the digital menu or profile","Optional table number for table ordering","Sits neatly on any table or counter"],"ar":["هيكل أكريليك شفاف فاخر","يفتح القائمة الرقمية أو الملف","رقم طاولة اختياري للطلب من الطاولة","يوضع بأناقة على أي طاولة أو كاونتر"],"ku":["دروستکراو لە ئەکریلیکی ڕوونی پرێمیۆم","مێنووی دیجیتاڵ یان پرۆفایل دەکاتەوە","ژمارەی مێزی هەڵبژاردەیی بۆ داواکاریی مێز","بە جوانی لەسەر هەر مێز یان کاونتێرێک دادەنرێت"]}'::jsonb, '{}'::jsonb, null, true, '["/brand/product-acrylic-stand.svg"]'::jsonb, '["clear"]'::jsonb, 'published', 3, true, '{"en":"Vee Acrylic NFC Stand","ar":"حامل Vee الأكريليك NFC","ku":"ستاندی ئەکریلیکی Vee NFC"}'::jsonb, '{"en":"A premium acrylic table stand for restaurants and cafés. One tap opens your digital menu or business profile, and can include a table number for table-base","ar":"حامل طاولة أكريليك فاخر للمطاعم والمقاهي. لمسة واحدة تفتح قائمتك الرقمية أو ملف عملك، ويمكن أن يتضمن رقم الطاولة للطلب من الطاولة.","ku":"ستاندێکی مێزی ئەکریلیکی پرێمیۆم بۆ چێشتخانە و کافێکان. یەک دەستلێدان مێنووی دیجیتاڵ یان پرۆفایلی بزنسەکەت دەکاتەوە، و دەتوانێت ژمارەی مێز لەخۆبگرێت بۆ داوا"}'::jsonb, 'enquire'
);
